{"code": "class N:
    def __init__(self, v):
        self.v, self.l, self.r = v, None, None

def insert(root, v):
    if root is None:
        return N(v)
    if v < root.v:
        root.l = insert(root.l, v)
    elif v > root.v:
        root.r = insert(root.r, v)
    return root

def inorder(root, acc=None):
    if acc is None:
        acc = []
    if root:
        inorder(root.l, acc)
        acc.append(root.v)
        inorder(root.r, acc)
    return acc

root = None
for v in [5, 3, 7, 2, 4]:
    root = insert(root, v)
print(inorder(root))
